def _row_to_poem(self, row: list[str]) -> dict | None:
    col = self._col

    def cell(name: str) -> str:
        i = col.get(name)
        return row[i].strip() if i is not None and i < len(row) else ""

    for key, want in self.select.items():
        if key not in col:
            sys.exit(f"--select 指定的列 {key!r} 不在表头里")
        got = cell(key)
        # 允许 列=值 子串匹配，或 列=~正则
        if want.startswith("~"):
            if not re.search(want[1:], got):
                return None
        elif want not in got:
            return None

    title = cell("title") or "无题"
    if self.title_re and not self.title_re.search(title):
        return None

    return {
        "title": title,
        "author": cell("author") or "佚名",
        "period": cell("period"),
        "category": cell("category"),
        "section": cell(self.group_by or "category") or "未分类",
        "paragraphs": cell("paragraphs"),
    }

def iter_poems(self):
    """逐首产出，跳过空行/被过滤的行。"""
    f, reader = self._open()
    taken = 0
    try:
        for row in reader:
            if not row or not any(c.strip() for c in row):
                continue
            poem = self._row_to_poem(row)
            if poem is None:
                continue
            yield poem
            taken += 1
            if self.limit and taken >= self.limit:
                print(f"[info] 已取满 --limit {self.limit} 首，停止读取", file=sys.stderr)
                return
    finally:
        f.close()

# ---- 主接口：按 (章节, 小节) 分好组后产出 ----
def groups(self, section_order=None, sort: bool = True):
    """产出 ((章节, 小节), [诗, ...])。

    CSV 里章节往往是打散的，所以要先把全书排序再分组，否则同一个体裁
    会在目录里重复出现很多次。数据量大时不让它全进内存：先写一份临时
    行文件，用系统的 sort 排序，再流式读回。
    """
    import json

    if not sort:
        cur_key, buf = None, []
        for poem in self.iter_poems():
            key = (poem["section"], poem["author"])
            if key != cur_key:
                if buf:
                    yield cur_key, buf
                cur_key, buf = key, []
            buf.append(poem)
        if buf:
            yield cur_key, buf
        return

    rank = {name: i for i, name in enumerate(section_order or [])}
    tmpdir = tempfile.mkdtemp(prefix="poetrypdf_")
    # 排序键：章节序号 → 小节 → 原始行号。行号用 0 填充定长，保证 sort 的
    # 字典序等于数值序；同组内保持原始出现顺序。
    width = 12
    try:
        for path_no, poem in enumerate(self.iter_poems()):
            shard = os.path.join(tmpdir, "part")
            with open(shard, "a", encoding="utf-8") as fo:
                sec_rank = rank.get(poem["section"], len(rank))
                key = f"{sec_rank:08d}\x1f{poem['section']}\x1f{poem['author']}\x1f{path_no:0{width}d}"
                fo.write(f"{key}\x1f{json.dumps(poem, ensure_ascii=False)}\n")
        shard = os.path.join(tmpdir, "part")
        if os.path.exists(shard):
            shard_sorted = os.path.join(tmpdir, "sorted")
            _external_sort(shard, shard_sorted)
            yield from _read_sorted_groups(shard_sorted)
    finally:
        import shutil
        shutil.rmtree(tmpdir, ignore_errors=True)

