def _external_sort(src: str, dst: str, chunk_bytes: int = 64 * 1024 * 1024) -> None:
    """按行排序。尽量用系统的 sort（走磁盘、快、内存友好），没有就回退到
    分块归并的纯 Python 实现。两边的排序规则一致：按整行字节序。"""
    if os.name != "nt":
        import shutil
        if shutil.which("sort"):
            env = dict(os.environ, LC_ALL="C")
            with open(dst, "wb") as out:
                rc = subprocess.call(["sort", "-t", "\x1f", "-k1,3", "-s", src],
                                     stdout=out, env=env)
            if rc == 0:
                return
    _merge_sort(src, dst, chunk_bytes)


def _merge_sort(src: str, dst: str, chunk_bytes: int) -> None:
    import heapq

    tmpdir = os.path.dirname(dst)
    chunks, buf, size = [], [], 0
    with open(src, "r", encoding="utf-8") as f:
        for line in f:
            buf.append((line.split("\x1f", 3)[0:3], line))
            size += len(line)
            if size >= chunk_bytes:
                buf.sort(key=lambda kv: kv[0])
                p = os.path.join(tmpdir, f"chunk{len(chunks)}")
                with open(p, "w", encoding="utf-8") as fo:
                    fo.writelines(ln for _k, ln in buf)
                chunks.append(p)
                buf, size = [], 0
    if buf:
        buf.sort(key=lambda kv: kv[0])
        p = os.path.join(tmpdir, f"chunk{len(chunks)}")
        with open(p, "w", encoding="utf-8") as fo:
            fo.writelines(ln for _k, ln in buf)
        chunks.append(p)

    if len(chunks) <= 1:
        if chunks:
            os.replace(chunks[0], dst)
        else:
            open(dst, "w").close()
        return

    files = [open(p, "r", encoding="utf-8") for p in chunks]
    try:
        def keyed(fh):
            for line in fh:
                yield line.split("\x1f", 3)[0:3], line

        with open(dst, "w", encoding="utf-8") as out:
            out.writelines(ln for _k, ln in heapq.merge(*[keyed(fh) for fh in files],
                                                        key=lambda kv: kv[0]))
    finally:
        for fh in files:
            fh.close()
        for p in chunks:
            try:
                os.unlink(p)
            except OSError:
                pass


def _read_sorted_groups(path: str):
    """读回排好序的行，合并成 ((章节, 小节), [诗]) 分组。"""
    import json

    cur_key, buf = None, []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.split("\x1f", 3)
            if len(parts) < 4:
                continue
            _rank, section, group, payload = parts
            key = (section, group)
            if key != cur_key:
                if buf:
                    yield cur_key, buf
                cur_key, buf = key, []
            buf.append(json.loads(payload))
    if buf:
        yield cur_key, buf


